from enum import Enum

class Mode(Enum):
    NOMINAL = 'nominal'
    DOWNLINK = 'downlink'
    SAFE = 'safe'

class FlightModeMachine:
    MINIMUM_FREE_BYTES = 4096

    def __init__(self, mode=Mode.NOMINAL):
        self.mode = mode

    def begin_downlink(self, *, contact_locked, free_bytes):
        if (self.mode is not Mode.NOMINAL or not contact_locked
                or free_bytes < self.MINIMUM_FREE_BYTES):
            return False
        self.mode = Mode.DOWNLINK
        return True

    def end_downlink(self):
        if self.mode is not Mode.DOWNLINK:
            return False
        self.mode = Mode.NOMINAL
        return True
